var markBookingPaid = async (session) => {
  const bookingId = session.metadata?.bookingId;
  if (!bookingId) return;
  if (session.payment_status !== "paid") return;
  const paymentIntentId = typeof session.payment_intent === "string" ? session.payment_intent : session.payment_intent?.id;
  const amount = (session.amount_total ?? 0) / 100;
  const existingPayment = await prisma.payment.findUnique({
    where: { bookingId }
  });
  if (existingPayment && existingPayment.status === "COMPLETED") {
    return;
  }
  await prisma.payment.upsert({
    where: { bookingId },
    create: {
      bookingId,
      amount,
      transactionId: paymentIntentId ?? session.id,
      provider: "STRIPE",
      status: "COMPLETED",
      stripeCheckoutSessionId: session.id,
      paidAt: /* @__PURE__ */ new Date()
    },
    update: {
      amount,
      transactionId: paymentIntentId ?? session.id,
      provider: "STRIPE",
      status: "COMPLETED",
      stripeCheckoutSessionId: session.id,
      paidAt: /* @__PURE__ */ new Date()
    }
  });
  await prisma.booking.update({
    where: { id: bookingId },
    data: { status: "PAID" }
  });
};
var handleCheckoutSessionFailed = async (session) => {
  const bookingId = session.metadata?.bookingId;
  if (!bookingId) return;
  const existingPayment = await prisma.payment.findUnique({
    where: { bookingId }
  });
  if (!existingPayment || existingPayment.status === "COMPLETED") {
    return;
  }
  await prisma.payment.update({
    where: { bookingId },
    data: { status: "FAILED" }
  });
};
var handleChargeRefunded = async (charge) => {
  const paymentIntentId = typeof charge.payment_intent === "string" ? charge.payment_intent : charge.payment_intent?.id;
  if (!paymentIntentId) return;
  const payment = await prisma.payment.findUnique({
    where: { transactionId: paymentIntentId }
  });
  if (!payment || payment.status === "REFUNDED") return;
  await prisma.payment.update({
    where: { id: payment.id },
    data: { status: "REFUNDED" }
  });
  await prisma.booking.update({
    where: { id: payment.bookingId },
    data: { status: "CANCELLED" }
  });
};
var handleStripeEvent = async (event) => {
  switch (event.type) {
    case "checkout.session.completed":
    case "checkout.session.async_payment_succeeded":
      await markBookingPaid(event.data.object);
      break;
    case "checkout.session.async_payment_failed":
      await handleCheckoutSessionFailed(event.data.object);
      break;
    case "charge.refunded":
      await handleChargeRefunded(event.data.object);
      break;
    default:
      break;
  }
};
